head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.tooltip = function(label, index) {
    return "itfewfejwifownflfjlwjfliewjfliewjfliewjflijfewlifjelwiafjwlfwfjiwlem " + index;
};
scwin.fireMouseHover = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.__triggerMouseover = function() {
    var el = document.getElementsByClassName('w2checkbox_label')[0];
    scwin.fireMouseHover(el);
}
scwin.checkVal = function() {
    debugger;
    var broswer_width = window.innerWidth - 150;
    var tooltip_left = parseInt(WebSquare.wUnit.getDomById($p.id + 'wq_uuid_2_tooltip').style.left, 10);
    return broswer_width > tooltip_left;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__triggerMouseover()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
